#!/usr/bin/env python3
"""Build the ranked scorer-derived results summary from ``metrics_long.csv``.

This reconstructs the manuscript Table 3 fields that are available directly
from scorer output. Supply ``--metrics`` once per locked execution; numeric
outcomes are averaged only after exact model/pass/cohort/type key matching and
configuration metadata must agree. The script reads the note-wide
(``phi_type == ALL``) rows for one pass and cohort, joins Pass 1 to calculate
the second-pass recall increment, ranks models by character recall, and prints
an aligned table; with ``--csv`` it also writes the selected rows to a file.
Published confidence limits require the matched per-note files processed by
``bootstrap_ci.py``; the timing column requires retained timing inputs and is
not generated by this scorer.

By default it uses the headline configuration reported in the paper -- the
cumulative two-pass predictions over every expected note::

    python scripts/make_results_table.py --metrics out/metrics_long.csv

For the three-execution study summary::

    python scripts/make_results_table.py --metrics run1/metrics_long.csv \\
        --metrics run2/metrics_long.csv --metrics run3/metrics_long.csv

Switch pass or cohort to inspect the other views the scorer emits::

    python scripts/make_results_table.py --metrics out/metrics_long.csv \\
        --pass pass1 --cohort operational_complete

Standard library only.
"""

from __future__ import annotations

import argparse
import csv
import os
from pathlib import Path
from typing import Optional

from metric_runs import load_averaged_metrics

# Columns shown, in order: (csv field, header, kind). "num" is a rate rendered
# to three decimals; "count" is an integer; "raw" is printed verbatim.
DISPLAY = [
    ("n_notes", "Notes", "count"),
    ("params_display", "Params(B)", "raw"),
    ("char_recall", "Recall", "num"),
    ("char_precision", "Prec", "num"),
    ("char_f1", "F1", "num"),
    ("delta_recall_pass2", "DeltaP2", "signed"),
    ("relaxed_span_f1", "SpanF1(+/-2)", "num"),
    ("zero_residual_notes", "Complete", "count"),
    ("usable_rate", "Usable", "num"),
]


def fmt(value: str, kind: str) -> str:
    """Render one cell; blank ('undefined') becomes a dash."""
    if value in ("", "None"):
        return "-"
    if kind == "num":
        return f"{float(value):.3f}"
    if kind == "signed":
        return f"{float(value):+.3f}"
    if kind == "count":
        number = float(value)
        return str(int(number)) if number.is_integer() else f"{number:.1f}"
    if kind == "flag":
        return {"True": "yes", "False": "", "1": "yes", "0": ""}.get(value, value)
    return value


def select_rows(metrics_paths, pass_label: str, cohort: str) -> list[dict[str, str]]:
    """Note-wide rows for one pass/cohort, ranked by descending character recall."""
    if isinstance(metrics_paths, (str, Path)):
        metrics_paths = [Path(metrics_paths)]
    all_rows = load_averaged_metrics(metrics_paths)
    rows = [
        dict(row) for row in all_rows
        if row["phi_type"] == "ALL" and row["pass"] == pass_label and row["cohort"] == cohort
    ]
    pass1 = {
        row["model_id"]: row for row in all_rows
        if row["phi_type"] == "ALL" and row["pass"] == "pass1" and row["cohort"] == cohort
    }
    for row in rows:
        total = row.get("params_total_B", "")
        effective = row.get("params_effective_B", "")
        active = row.get("params_active_B", "")
        suffix = effective if effective not in ("", "None") else active
        row["params_display"] = (
            f"{float(total):.1f}/{float(suffix):.1f}" if total not in ("", "None")
            and suffix not in ("", "None") else total
        )
        baseline = pass1.get(row["model_id"])
        if pass_label == "cumulative_pass2" and cohort == "all_expected" and baseline:
            current = row.get("char_recall", "")
            prior = baseline.get("char_recall", "")
            if current not in ("", "None") and prior not in ("", "None"):
                row["delta_recall_pass2"] = str(float(current) - float(prior))
        else:
            row["delta_recall_pass2"] = ""
    rows.sort(key=lambda r: float(r["char_recall"]) if r["char_recall"] not in ("", "None") else -1.0,
              reverse=True)
    return rows


def render_table(rows: list[dict[str, str]]) -> str:
    """Format the ranked rows as a fixed-width text table."""
    headers = ["#", "model_id"] + [head for _, head, _ in DISPLAY]
    lines = [[str(i)] + [row["model_id"]] + [fmt(row.get(field, ""), kind)
                                             for field, _, kind in DISPLAY]
             for i, row in enumerate(rows, start=1)]

    widths = [len(h) for h in headers]
    for line in lines:
        widths = [max(w, len(cell)) for w, cell in zip(widths, line)]

    def join(cells: list[str]) -> str:
        # First two columns left-aligned (rank, name); numeric columns right.
        out = [cells[0].ljust(widths[0]), cells[1].ljust(widths[1])]
        out += [cell.rjust(w) for cell, w in zip(cells[2:], widths[2:])]
        return "  ".join(out)

    body = [join(headers), join(["-" * w for w in widths])]
    body += [join(line) for line in lines]
    return "\n".join(body)


def write_csv(path: Path, rows: list[dict[str, str]]) -> None:
    path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    fields = ["rank", "model_id"] + [field for field, _, _ in DISPLAY]
    with path.open("w", newline="", encoding="utf-8") as stream:
        writer = csv.DictWriter(stream, fieldnames=fields, extrasaction="ignore")
        writer.writeheader()
        for rank, row in enumerate(rows, start=1):
            writer.writerow({"rank": rank, "model_id": row["model_id"],
                             **{field: row.get(field, "") for field, _, _ in DISPLAY}})
    path.chmod(0o600)


def main(argv: Optional[list[str]] = None) -> int:
    os.umask(0o077)
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--metrics", type=Path, action="append", default=None,
                        help="metrics_long.csv for one execution; repeat for all three study executions")
    parser.add_argument("--pass", dest="pass_label", default="cumulative_pass2",
                        choices=["pass1", "cumulative_pass2"],
                        help="which pass to report (default: cumulative_pass2)")
    parser.add_argument("--cohort", default="all_expected",
                        choices=["all_expected", "operational_complete"],
                        help="which cohort to report (default: all_expected)")
    parser.add_argument("--csv", type=Path, default=None,
                        help="optional path to also write the ranked table as CSV")
    args = parser.parse_args(argv)

    metrics_paths = args.metrics or [Path("out/metrics_long.csv")]
    for metrics_path in metrics_paths:
        if not metrics_path.exists():
            parser.error(f"metrics file not found: {metrics_path}")

    try:
        rows = select_rows(metrics_paths, args.pass_label, args.cohort)
    except ValueError as exc:
        parser.error(str(exc))
    if not rows:
        parser.error(f"no ALL rows for pass={args.pass_label} cohort={args.cohort}")

    print(f"# {args.pass_label} / {args.cohort} -- {len(rows)} models, "
          f"{len(metrics_paths)} execution(s), ranked by character recall\n")
    print(render_table(rows))
    if args.csv:
        write_csv(args.csv, rows)
        print(f"\nwrote {len(rows)} rows -> {args.csv}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
